import{_ as o,l as i,o as t,c as n,v as e,p as s,x as r,d as m,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"资金费率与标记价格","description":"","frontmatter":{"title":"资金费率与标记价格","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/crypto-mark-price.md","filePath":"quant/crypto-mark-price.md","lastUpdated":1789023840000}'),h={name:"quant/crypto-mark-price.md"};function E(c,a,B,_,u,A){const l=i("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="资金费率与标记价格" tabindex="-1">资金费率与标记价格 <a class="header-anchor" href="#资金费率与标记价格" aria-label="Permalink to &quot;资金费率与标记价格&quot;">​</a></h1><div class="epigraph"><p>永续合约的最后成交可以在薄簿上被扫到离谱的价格；标记价格用指数与基差把结算和强平钉在更难被单笔打印操纵的参照上。资金费也按标记而不是按最后成交来算。</p><footer>—— 据主要永续合约场所公开的标记价格与资金费公式整理</footer></div><p><a href="/quant/stablecoin-depeg">上一课</a>写稳定币锚靠一级赎回与储备信念维持，脱锚冲击计价、保证金、清算与稳定对 AMM。<a href="/quant/crypto-perp-funding">永续合约资金费率</a>已经写出资金费会计，并提到标记价格用于结算与强平。缺口是把<strong>标记价格对最后成交</strong>写成一等对象：为什么强平不能钉 last trade、标记如何合成、它如何反向进入资金费与清算连锁。本课假定指数仍可计算（脱锚是上一课的状态），问标记与成交为何分叉。不重写脱锚路径。加密微观结构课序在此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最后成交 \\(P_{\\mathrm{last}}\\) 是匹配引擎的打印，可以在深度不足时远离指数 \\(S\\)。若强平与未实现盈亏用 \\(P_{\\mathrm{last}}\\)，一笔针价可以连锁清算，制造更多打印，再清算。标记价格 \\(P_{\\mathrm{mark}}\\) 通常是：现货指数加衰减的基差，或冲击买卖价相对指数的夹紧组合，再加保护以免偏离指数过远。资金费的基数也是 \\(P_{\\mathrm{mark}}\\)。缺口是回测与风控必须走标记路径：用 K 线收盘（往往是 last）去模拟强平，会高估爆仓次数；用标记去当成交价，又会低估滑点。两套价格都要存。</p><p>资金费课已经给出 \\(\\mathrm{Funding}=q\\cdot P_{\\mathrm{mark}}\\cdot r_{\\mathrm{fund}}\\)。本课补：\\(P_{\\mathrm{mark}}\\) 的滞后与夹紧如何使资金费对瞬时针价不敏感，以及这种不敏感如何把风险从资金费赶到清算引擎的另一条规则（例如保险基金、自动减仓）。</p><h3 id="标记不是中点-也不是公允价格" tabindex="-1">标记不是中点，也不是公允价格 <a class="header-anchor" href="#标记不是中点-也不是公允价格" aria-label="Permalink to &quot;标记不是中点，也不是公允价格&quot;">​</a></h3><p>股票中点来自 BBO。永续标记来自跨场所指数加合约基差。指数成分加权、异常过滤、停牌处理，决定 \\(S\\) 的质量。单一现货场所宕机或脱锚时，\\(S\\) 与 \\(P_{\\mathrm{mark}}\\) 可以同时失真——稳定币课的对象。即使指数完好，\\(P_{\\mathrm{mark}}\\) 仍可能与本所可成交价差很远：本所簿已经跳了，标记还在平滑。此时你「按标记看起来没爆」，按可成交价已经穿维持保证金。风控应同时盯：标记保证金（交易所规则）与本所可执行价保证金（经济）。</p><p><span class="marginnote">各场所公式不同：有的用移动平均基差，有的用冲击中间价。不能把 A 所的标记历史接到 B 所的成交上算资金。参数变更日要切断样本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>存储：<code>trade_px</code>, <code>mark_px</code>, <code>index_px</code>，以及资金费结算事件。强平回测用标记触及维持水平，再叠加本所深度能否在该时刻真的平掉——后者往往不能，这就是连锁。统计：\\(|P_{\\mathrm{last}}-P_{\\mathrm{mark}}|\\) 的尾部、针价期间标记是否夹紧、夹紧时资金费是否仍被公式上限挡住。执行 TCA 用成交价相对当时标记与相对当时本所中点两套：前者对永续会计，后者对短时交易摩擦。</p><p>与股票实现价差对照：股票用中点盯市；永续若用 last 盯市，实现「价差」会被针价主导。研究永续做市，盯市应用标记，成交成本仍用 last 相对本所簿。</p><h3 id="标记、资金与清算的分工" tabindex="-1">标记、资金与清算的分工 <a class="header-anchor" href="#标记、资金与清算的分工" aria-label="Permalink to &quot;标记、资金与清算的分工&quot;">​</a></h3><p>资金费缓慢地把 \\(F\\) 拉向 \\(S\\)，周期以小时计。标记使盘中盈亏与强平不跟针走。清算引擎在标记触及阈值时触发。三件套一起，才是永续的「价格」。缺标记的回测不是永续回测。自动减仓与保险基金是标记之后的分配规则，本课只要求：触发用标记，分配用场所规则，不要用 last 自行发明强平。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最后成交是连续匹配的输出，继承股票 LOB 的全部微观结构，包括薄簿冲击。指数是一篮子现货的滤波。标记是把合约交易价与指数之间的缝补上，并切断单笔打印到保证金的传导。机制目的是降低操纵与连锁，不是给出无套利的理论价格。无套利仍靠资金费与基差交易。当 \\(P_{\\mathrm{last}}\\) 与 \\(P_{\\mathrm{mark}}\\) 分叉很大，要么深度极差，要么指数滞后，要么两者都有。这是状态，应进入风控，而不是进入「alpha」。</p><p><span class="marginnote">不要用 <a href="/quant/kyle-model">Kyle</a> 的 \\(p=\\mu+\\lambda y\\) 去解释标记。标记不是均衡交易价，是风控参照。lambda 若要估，用成交价或本所中点，并剔除明显针价。</span></p>',17)),(t(),s(p,null,{default:r(()=>[d(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TB%0A%20%20L%5B%22%E6%9C%80%E5%90%8E%E6%88%90%E4%BA%A4%20last%22%5D%20--%3E%20MCH%5B%22%E6%92%AE%E5%90%88%E4%B8%8E%E6%BB%91%E7%82%B9%22%5D%0A%20%20X%5B%22%E7%8E%B0%E8%B4%A7%E6%8C%87%E6%95%B0%22%5D%20--%3E%20MK%5B%22%E6%A0%87%E8%AE%B0%E4%BB%B7%E6%A0%BC%20mark%22%5D%0A%20%20B%5B%22%E5%9F%BA%E5%B7%AE%20%2F%20%E5%86%B2%E5%87%BB%E4%B8%AD%E9%97%B4%E4%BB%B7%22%5D%20--%3E%20MK%0A%20%20MK%20--%3E%20F%5B%22%E8%B5%84%E9%87%91%E8%B4%B9%E5%9F%BA%E6%95%B0%22%5D%0A%20%20MK%20--%3E%20LIQ%5B%22%E5%BC%BA%E5%B9%B3%E4%B8%8E%E6%9C%AA%E5%AE%9E%E7%8E%B0%E7%9B%88%E4%BA%8F%22%5D%0A%20%20L%20--%3E%20SPIKE%5B%22%E9%92%88%E4%BB%B7%22%5D%0A%20%20SPIKE%20-.-%3E%7C%22%E5%88%87%E6%96%AD%22%7C%20LIQ%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="可执行价穿仓与标记未穿仓可以同时发生" tabindex="-1">可执行价穿仓与标记未穿仓可以同时发生 <a class="header-anchor" href="#可执行价穿仓与标记未穿仓可以同时发生" aria-label="Permalink to &quot;可执行价穿仓与标记未穿仓可以同时发生&quot;">​</a></h3><p>本所簿已远离指数，标记仍被夹紧时，交易所规则可能尚未强平，经济上已无法按标记退出。风控应并行盯两套保证金：规则的与可执行的。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>传统期货用结算价与涨跌停，也有别于 last，但通常有交割收敛。永续没有到期，标记与资金是永久替代。TradFi 股票没有对等的 mark price 强平机制（保证金用另套估值）。本课不讨论如何攻击指数成分。附录市场数据课与股票 SIP 不同，加密是各所各自的标记。</p><p><span class="marginnote">跨所拼接标记路径会把公式差异写成基差 alpha。参数变更日切断样本，比拼接后做体制检验更干净。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>永续必须同时使用 last（成交与滑点）和 mark（资金、盈亏、强平）。</li><li>标记切断针价到清算的传导，不保证等于可成交价。</li><li>资金费按标记计算，对瞬时 last 不敏感；风险被推到清算规则。</li><li>回测用 K 线 last 会高估爆仓；用 mark 当成交价会低估滑点。</li><li>公式随场所与日期而变，禁止跨所拼接标记。</li><li>出处：各主要场所公开的标记价格与资金费文档；资金费会计见上一课；清算连锁见本课序相关叶子。</li></ul>',7))])}const f=o(h,[["render",E]]);export{P as __pageData,f as default};
